-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'French Apartment';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'French Apartment'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'French Apartment'; END IF;
END $$;

UPDATE societies SET status = 'active' WHERE name = 'French Apartment';   -- address left as stored

INSERT INTO engagements (id, society_id, service_line, status, created_at)
SELECT 'bf-french-apartment-eng', s.id, 'lighting', 'active', now() FROM societies s WHERE s.name = 'French Apartment' ON CONFLICT DO NOTHING;

INSERT INTO pipelines (id, society_id, service_line, stage, contact_name, contact_phone,
                       meeting_date, sales_owner_id, logged_by_id, authoritative, notes,
                       created_at, updated_at)
SELECT 'bf-french-apartment-pipe', s.id, 'lighting', 'active_billing',
       'French Apartment', NULL, '2026-03-18'::date,
       a.id, a.id, true,
       'Backfilled from the signed agreement, the post-installation savings report and the first invoice. This deal predates the system: the date above is the agreement signature, not a meeting.',
       now(), now()
FROM societies s, admin_users a WHERE s.name = 'French Apartment' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO site_surveys (id, pipeline_id, created_at) VALUES ('bf-french-apartment-survey', 'bf-french-apartment-pipe', now()) ON CONFLICT DO NOTHING;

INSERT INTO circuits (id, society_id, site_survey_id, service_line, light_type,
                      metered_light_count, represented_light_count, wattage, working_hours,
                      state, location, meter_installed_at, light_replacement_date,
                      pre_install_baseline, benchmark_savings_pct, eligibility_checklist,
                      created_by_id, created_at)
SELECT 'bf-french-apartment-ckt-1', s.id, 'bf-french-apartment-survey', 'lighting', 'basement',
       55, 1066, 20, 24,
       'benchmark_confirmed', 'Basement',
       '2025-11-04'::date, '2025-11-14'::date,
       25.00, 64.36,
       jsonb_build_object('backfilled', true, 'source', 'signed agreement + post-installation savings report',
                          'note', 'Commissioned before this system existed — CON-16 eligibility was never assessed.',
                          'deviations', '["eligibility-never-assessed", "dates-inferred-from-readings", "benchmark-single-demo"]'::jsonb,
                          'basisNote', '55 tube lights at 20W running 24h; theoretical 26.40 kWh/day against a measured 25.00, a -5.32% variance the report records as within its +/-10% range. NO OVERRIDE: (25.00-8.91)/25.00 = 64.3600%, exactly the agreed 64.36%. Both tables reproduce their stated averages - 6 pre days 05-10 Nov 2025 average 24.9967 against 25.00, 4 post days 15-18 Nov average 8.9050 against 8.91. The post table is headed ''Savings % w.r.t 20.24 kWh'', which is a leftover: its own percentages only work against 25.00 (9.15 gives the stated 63.40% against 25.00, not against 20.24). Same shape as Amrapali Princely Estate''s ''w.r.t 23.96''. Neither date is stated: meter install taken as the day before the first pre-install reading (05 Nov 2025), replacement as the day before the post-install readings start (15 Nov).'),
       a.id, now()
FROM societies s, admin_users a WHERE s.name = 'French Apartment' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;
INSERT INTO lighting_inventory_areas (id, site_survey_id, area, light_type, count, method, note, created_at)
VALUES ('bf-french-apartment-ckt-1-inv', 'bf-french-apartment-survey', 'Basement', 'basement',
        1066, 'estimated',
        'Read from the society''s own documents — its first invoice and post-installation savings report. The site was never walked; this society was commissioned before this system existed.',
        now()) ON CONFLICT DO NOTHING;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM device_types WHERE name = 'Tube light 20W' AND role = 'original' AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'device type % is not in the catalog', 'Tube light 20W';
  END IF;
END $$;
INSERT INTO circuit_devices (id, circuit_id, device_type_id, count, wattage, hours_per_day,
                             excluded_from_calculation, historical, historical_note, recorded_by_id, created_at)
SELECT 'bf-french-apartment-ckt-1-dev-1', 'bf-french-apartment-ckt-1', dt.id, 55, 20, 24,
       false, true, 'Read from the post-installation savings report', a.id, now()
FROM device_types dt, admin_users a
WHERE dt.name = 'Tube light 20W' AND dt.role = 'original' AND dt.deleted_at IS NULL
  AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;
