-- The demo report. Not needed for billing, but without it the deal map sits
-- at "Demo savings report · In progress" while every later step reads done.
INSERT INTO demo_reports (id, pipeline_id, version, status,
                          pre_install_baseline_total, post_install_average_total, measured_savings_pct,
                          society_light_count, metered_light_count, extrapolation_factor,
                          projected_savings_kwh_per_day, circuit_snapshot, generated_at, shared_at, shared_by_id)
SELECT 'bf-french-apartment-demo-report', 'bf-french-apartment-pipe', 1, 'shared',
       c.pre_install_baseline, c.pre_install_baseline * (1 - c.benchmark_savings_pct / 100),
       c.benchmark_savings_pct, c.represented_light_count, c.metered_light_count,
       c.represented_light_count::double precision / c.metered_light_count,
       (c.pre_install_baseline * c.benchmark_savings_pct / 100)
         * (c.represented_light_count::double precision / c.metered_light_count),
       '[{"circuitId": "bf-french-apartment-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 55, "representedLightCount": 1066, "extrapolationFactor": 19.381818, "preInstallBaseline": 25.0, "postInstallAverage": 8.91, "savedKwhPerDay": 16.09, "benchmarkSavingsPct": 64.36, "projectedSavedKwhPerDay": 311.8535, "preInstallReadings": [], "postInstallReadings": []}]'::jsonb, now(), '2026-03-18'::date, a.id
FROM circuits c, admin_users a
-- shared_by_id is an ADMIN, not a profile: FirsThing shares the report WITH
-- the society, so the sharer is internal. The mirror of offers, where
-- responded_by_id IS a profile because accepting is the society's act.
WHERE c.id = 'bf-french-apartment-ckt-1' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO offers (id, pipeline_id, version, status, benchmark_source, circuit_terms,
                    tolerance_pct, revenue_share_pct, unit_electricity_rate, term_months,
                    projected_monthly_fee, issued_at, issued_by_id, responded_at, responded_by_id, created_at)
SELECT 'bf-french-apartment-offer', 'bf-french-apartment-pipe', 1, 'accepted', 'negotiated_fixed', '[{"circuitId": "bf-french-apartment-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 55, "representedLightCount": 1066, "benchmarkSavingsPct": 64.36, "preInstallBaseline": 25.0, "projectedSavedKwhPerDay": 16.09}]'::jsonb,
       5, 58, 6.15, 36,
       24165.52, '2026-03-18'::date, a.id,
       '2026-03-18'::date, p.id, now()
FROM admin_users a
LEFT JOIN societies soc ON soc.name = 'French Apartment'
LEFT JOIN profiles p ON p.society_id = soc.id AND p.portal_authority = 'office_bearer' AND p.is_active
WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at, deviation_note,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-french-apartment-agreement', 'bf-french-apartment-pipe', 'bf-french-apartment-offer', '2026-03-18'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2026-03-18'::date, '2026-03-18'::date,
       '2026-03-18'::date,
       -- How this deal's figures were arrived at, in the field named for it.
       -- These societies predate the system and share no single method, so
       -- the basis travels with the agreement rather than living in a CSV.
       'Commissioned before this system existed. There was no single method across these societies, so how this deal''s figures were arrived at is recorded here rather than assumed. Departures from the standard: extrapolation-measured, billing-predates-agreement-execution, agreement-re-executed-after-changes. SOURCE IS THE USER''S PASTED TEXT for the agreement and demo report (2026-08-28). Every figure reconciles to the paisa: the pre-installation consumption 14,536.36 kWh/month is the demo''s MEASURED 25.00 kWh/day extrapolated over 55 lights to 1,066 (25.00/55 x 1066 x 30) - exact, not rounded - and 64.36% of it at Rs 6.15 gives Rs 57,536.94, split 58/42 for FirsThing''s Rs 24,165.52. 1,066 agreed and 1,066 installed, so the minimum clause does not bite. BILLING PREDATES EXECUTION, and the agreement says so itself: clause 21 sets the effective date at 24 Feb 2026 but the billing period at 1 Jan 2026 to 31 Dec 2028. It was then notarised and signed on 18 Mar 2026, a SECOND execution after changes - an earlier version was signed before Dec 2025 and is not on file (the user). So the contract on record was executed more than two months after the billing it governs began. The dates held here are the second signing. First invoice is for Jan 2026, so installation finished on or before 31 Dec 2025. Tolerance +/-5%, stated twice - in clause 6 and again in the performance guarantee. The demo report''s own ''42% of these verified savings'' AGREES with the agreement''s 58/42, unlike most of these.',
       'Documents/French_Apartment/2026-03/Agreements/French_Apartment_Agreement_2026-03-18.pdf',
       'French_Apartment_Agreement_2026-03-18.pdf',
       -- The scan reaches us the day after signing.
       ('2026-03-18'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO contracts (id, pipeline_id, society_id, service_line, agreement_id, status,
                       term_start, term_end, activated_at, activated_by_id, created_at)
SELECT 'bf-french-apartment-contract', 'bf-french-apartment-pipe', s.id, 'lighting', 'bf-french-apartment-agreement', 'active',
       '2026-01-01'::date, ('2026-01-01'::date + '36 months'::interval),
       '2026-01-01'::date, a.id, now()
FROM societies s, admin_users a WHERE s.name = 'French Apartment' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

