SELECT 'bf-french-apartment-terms', 'bf-french-apartment-contract', 1, '2026-01-01'::date, 'negotiated_fixed',
       5, 58, 6.15,
       '[{"circuitId": "bf-french-apartment-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 55, "representedLightCount": 1066, "benchmarkSavingsPct": 64.36, "preInstallBaseline": 25.0, "projectedSavedKwhPerDay": 16.09}]'::jsonb, a.id, now()
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;
